<template>
  <div class="view log-center">
    <div class="view-head"><div><h1 class="view-title">日志中心</h1><div class="view-sub">{{ currentHost?.name || '未选择主机' }} · systemd 与 Docker 日志长期检索</div></div><div class="status"><span class="dot" :class="status.ready?'ok':'warn'"></span>{{ statusText }}</div></div>
    <div v-if="error" class="notice error">{{ error }}</div>
    <section class="card collector-card"><div class="collector-head"><div><h3>日志采集覆盖</h3><span class="muted">默认不访问 Loki，点击“检测采集”才检查最近日志</span></div><div class="collector-actions"><button class="btn btn-sm" :disabled="agentLoading" @click="loadAgentOverview(false)">刷新状态</button><button class="btn btn-sm" :disabled="agentLoading||!status.ready" @click="loadAgentOverview(true)">{{ agentLoading?'检测中…':'检测采集' }}</button><button class="btn btn-sm" :disabled="agentLoading||!status.configured" @click="deployMissing">部署缺失采集器</button></div></div><div class="coverage-grid"><div><span>覆盖率</span><b>{{ agentOverview.coverage_percent || 0 }}%</b></div><div><span>主机总数</span><b>{{ agentOverview.total || 0 }}</b></div><div><span>采集器运行</span><b>{{ agentOverview.running || 0 }}</b></div><div><span>{{ agentOverview.probed?'10分钟内有日志':'异常/待处理' }}</span><b>{{ agentOverview.probed?(agentOverview.fresh||0):(agentOverview.abnormal||0) }}</b></div></div><div class="collector-table"><table class="table"><thead><tr><th>主机</th><th>采集器</th><th>最近日志</th><th>诊断</th><th>操作</th></tr></thead><tbody><tr v-for="item in agentOverview.agents||[]" :key="item.server_id"><td><b>{{ item.name }}</b><small class="mono">{{ item.host }}</small></td><td><span class="agent-state" :class="agentStateClass(item.collector_status)">{{ agentStateLabel(item.collector_status) }}</span><small v-if="item.collector_version">v{{ item.collector_version }}</small></td><td>{{ ingestionLabel(item) }}</td><td><span class="diagnostic" :class="item.diagnostic_level">{{ item.diagnostic }}</span></td><td><button v-if="!item.is_local&&item.has_credentials&&item.collector_status!=='running'" class="link-btn" :disabled="['deploying','checking'].includes(item.collector_status)||!status.configured" @click="deployAgent(item)">部署</button><span v-else-if="item.is_local" class="muted">中心栈</span><span v-else>-</span></td></tr><tr v-if="!(agentOverview.agents||[]).length"><td colspan="5" class="empty">暂无主机</td></tr></tbody></table></div></section>
    <section class="card loki-health"><div class="collector-head"><div><h3>Loki 存储健康</h3><span class="muted">磁盘水位、近 24 小时索引与官方运行指标</span></div><button class="btn btn-sm" :disabled="healthLoading||!status.configured" @click="loadHealth">{{ healthLoading?'读取中…':'刷新健康度' }}</button></div><div v-if="(health.warnings||[]).length" class="health-warnings"><span v-for="item in health.warnings" :key="item">{{ item }}</span></div><div class="health-grid"><div><span>数据盘使用率</span><b :class="{danger:(health.data_dir?.used_percent||0)>=80}">{{ health.data_dir?.available?`${health.data_dir.used_percent}%`:'-' }}</b><small>{{ health.data_dir?.available?`${fmtBytes(health.data_dir.used_bytes)} / ${fmtBytes(health.data_dir.total_bytes)}`:health.data_dir?.path||'未配置路径' }}</small></div><div><span>24小时日志条数</span><b>{{ health.index_24h?.entries ?? '-' }}</b><small>索引估算 · {{ fmtBytes(health.index_24h?.bytes) }}</small></div><div><span>累计接收行数</span><b>{{ health.runtime?.received_lines_total ?? '-' }}</b><small>{{ fmtBytes(health.runtime?.received_bytes_total) }}</small></div><div><span>累计写入异常</span><b :class="{danger:healthFailures>0}">{{ healthFailures }}</b><small>丢弃 / 5xx / 超时 / panic</small></div><div><span>Flush 队列</span><b :class="{danger:(health.runtime?.flush_queue_length||0)>0}">{{ health.runtime?.flush_queue_length ?? '-' }}</b><small>应长期保持 0</small></div></div></section>
    <section class="card toolbar">
      <div class="range-row"><b>时间段</b><button v-for="item in ranges" :key="item.key" class="range-btn" :class="{active:rangeKey===item.key}" @click="selectRange(item.key)">{{ item.label }}</button></div>
      <div v-if="rangeKey==='custom'" class="custom"><input v-model="customStart" type="datetime-local" /><span>至</span><input v-model="customEnd" type="datetime-local" /></div>
      <div class="filters"><select v-model="source"><option value="all">全部来源</option><option value="journal">systemd / journal</option><option value="docker">Docker 容器</option></select><input v-model.trim="service" maxlength="160" placeholder="服务名（精确，可选）" @keyup.enter="loadLogs" /><input v-model="search" maxlength="256" placeholder="日志关键字" @keyup.enter="loadLogs" /><select v-model.number="limit"><option :value="200">200 条</option><option :value="500">500 条</option><option :value="1000">1000 条</option><option :value="5000">5000 条</option></select><button class="btn" :disabled="loading||!status.ready" @click="loadLogs">{{ loading?'查询中…':'查询' }}</button></div>
    </section>
    <div class="stats-grid"><article class="card stat"><span>日志总量</span><b>{{ stats.total ?? 0 }}</b><small>当前时间段</small></article><article class="card stat danger"><span>错误日志</span><b>{{ stats.error_count ?? 0 }}</b><small>{{ errorRate }}%</small></article><article class="card stat"><span>systemd</span><b>{{ stats.sources?.journal || 0 }}</b><small>{{ sourceRate('journal') }}%</small></article><article class="card stat"><span>Docker</span><b>{{ stats.sources?.docker || 0 }}</b><small>{{ sourceRate('docker') }}%</small></article></div>
    <section class="card trend-card"><div class="result-head"><div><h3>日志量趋势</h3><span class="muted">自动按 {{ trendStep }} 分桶 · 蓝色为全部日志，红色为错误关键字</span></div></div><div ref="trendEl" class="trend-chart"></div></section>
    <section v-if="stats.top_services?.length" class="card service-stats"><h3>Top 日志服务</h3><div class="service-bars"><button v-for="item in stats.top_services" :key="item.name" @click="service=item.name;loadLogs()"><span>{{ item.name }}</span><i><em :style="{width:serviceWidth(item.count)}"></em></i><b>{{ item.count }}</b></button></div></section>
    <section class="card results">
      <div class="result-head"><div><h3>日志记录</h3><span class="muted">{{ entries.length }} 条 · 保留 {{ status.retention_days || 365 }} 天 · 不自动刷新</span></div><button class="btn btn-sm" :disabled="!entries.length" @click="exportText">导出</button></div>
      <div v-if="loading" class="empty">正在检索日志…</div>
      <div v-else-if="!entries.length" class="empty">{{ status.ready?'当前条件暂无日志':'请先部署或检查 Loki / Alloy' }}</div>
      <div v-else class="log-list"><div v-for="(entry,index) in entries" :key="`${entry.timestamp_ns}-${index}`" class="log-line"><time>{{ formatTime(entry.timestamp_ns) }}</time><span class="source" :class="entry.labels?.source">{{ entry.labels?.source || '-' }}</span><span class="service">{{ entry.labels?.service_name || entry.labels?.unit || entry.labels?.container || '-' }}</span><pre>{{ entry.line }}</pre></div></div>
    </section>
  </div>
</template>

<script setup>
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { api, fmtBytes, fmtTime, toast } from '../api'
import { useHostContext } from '../hostContext'

const { selectedHostId, currentHost, refreshHosts }=useHostContext()
const status=reactive({configured:false,ready:false,retention_days:365,message:''}),stats=reactive({total:0,error_count:0,sources:{},levels:{},top_services:[]}),entries=ref([]),loading=ref(false),error=ref('')
const agentOverview=reactive({total:0,running:0,fresh:0,abnormal:0,coverage_percent:0,probed:false,agents:[]}),agentLoading=ref(false)
const health=reactive({configured:false,data_dir:{},runtime:{},index_24h:{},warnings:[]}),healthLoading=ref(false)
const trend=ref({total:[],errors:[]}),trendEl=ref(null),trendStepSeconds=ref(60)
const source=ref('all'),service=ref(''),search=ref(''),limit=ref(500),rangeKey=ref('1h'),customStart=ref(''),customEnd=ref('')
const ranges=[{key:'15m',label:'15分钟',minutes:15},{key:'1h',label:'1小时',minutes:60},{key:'6h',label:'6小时',minutes:360},{key:'24h',label:'24小时',minutes:1440},{key:'7d',label:'7天',minutes:10080},{key:'30d',label:'30天',minutes:43200},{key:'90d',label:'90天',minutes:129600},{key:'1y',label:'1年',minutes:525600},{key:'custom',label:'自定义'}]
const statusText=computed(()=>!status.configured?'未配置 Loki':status.ready?'日志存储正常':'Loki 不可用')
const errorRate=computed(()=>stats.total?((stats.error_count||0)*100/stats.total).toFixed(1):'0.0')
const healthFailures=computed(()=>['discarded_samples_total','write_5xx_total','append_timeouts_total','panic_total'].reduce((sum,key)=>sum+Number(health.runtime?.[key]||0),0))
const trendStep=computed(()=>trendStepSeconds.value<3600?`${trendStepSeconds.value/60} 分钟`:`${trendStepSeconds.value/3600} 小时`)
let controller=null,chart=null
function localInput(value){const shifted=new Date(value.getTime()-value.getTimezoneOffset()*60000);return shifted.toISOString().slice(0,16)}
function range(){const end=rangeKey.value==='custom'&&customEnd.value?new Date(customEnd.value):new Date();const meta=ranges.find(item=>item.key===rangeKey.value);const start=rangeKey.value==='custom'&&customStart.value?new Date(customStart.value):new Date(end.getTime()-(meta?.minutes||60)*60000);if(start>=end)throw new Error('开始时间必须早于结束时间');return{start,end}}
function selectRange(key){rangeKey.value=key;if(key==='custom'){const end=new Date(),start=new Date(end.getTime()-3600000);customStart.value=localInput(start);customEnd.value=localInput(end)}}
async function loadStatus(){try{Object.assign(status,await api.get('/logs/status'))}catch(e){error.value=e.message}}
async function loadAgentOverview(probe=false){agentLoading.value=true;try{Object.assign(agentOverview,await api.get('/logs/agents/overview',{probe}))}catch(e){error.value=e.message}finally{agentLoading.value=false}}
async function loadHealth(){healthLoading.value=true;try{Object.assign(health,await api.get('/logs/health'))}catch(e){error.value=e.message}finally{healthLoading.value=false}}
async function deployMissing(){agentLoading.value=true;try{const data=await api.post('/logs/agents/deploy-missing');toast(`已安排 ${data.accepted||0} 台主机部署日志采集器`,'ok');await loadAgentOverview(false)}catch(e){toast(`部署失败：${e.message}`,'err')}finally{agentLoading.value=false}}
async function deployAgent(item){agentLoading.value=true;try{await api.post(`/servers/${item.server_id}/logs/agent/deploy`);toast(`${item.name} 已进入后台部署`,'ok');await loadAgentOverview(false)}catch(e){toast(`部署失败：${e.message}`,'err')}finally{agentLoading.value=false}}
function agentStateLabel(value){return({running:'运行中',deploying:'部署中',checking:'检查中',stopped:'已停止',error:'异常',not_deployed:'未部署',unknown:'未检查'})[value]||'未检查'}
function agentStateClass(value){return value==='running'?'ok':value==='error'?'error':['deploying','checking'].includes(value)?'info':'warn'}
function ingestionLabel(item){if(item.ingestion_status==='fresh')return `${fmtTime(item.last_log_at)}（新鲜）`;if(item.ingestion_status==='stale')return `${fmtTime(item.last_log_at)}（延迟）`;if(item.ingestion_status==='no_data')return '24小时无日志';if(item.ingestion_status==='error')return '探测失败';return '未检测'}
async function loadLogs(){if(!selectedHostId.value||!status.ready)return;controller?.abort();controller=new AbortController();const active=controller;loading.value=true;error.value='';try{const {start,end}=range();const query={start:start.toISOString(),end:end.toISOString(),source:source.value,service:service.value,search:search.value};const [data,summary,timeline]=await Promise.all([api.get(`/servers/${selectedHostId.value}/logs/query`,{...query,limit:limit.value,direction:'backward'},{signal:active.signal}),api.get(`/servers/${selectedHostId.value}/logs/stats`,query,{signal:active.signal}),api.get(`/servers/${selectedHostId.value}/logs/timeseries`,query,{signal:active.signal})]);entries.value=data.entries||[];Object.assign(stats,summary);trend.value=timeline.series||{total:[],errors:[]};trendStepSeconds.value=timeline.step_seconds||60;await nextTick();renderTrend()}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{if(controller===active)loading.value=false}}
function renderTrend(){if(!trendEl.value)return;chart ||= echarts.init(trendEl.value);chart.setOption({tooltip:{trigger:'axis'},legend:{data:['全部日志','错误日志']},grid:{left:52,right:18,top:42,bottom:38},dataZoom:[{type:'inside'}],xAxis:{type:'time'},yAxis:{type:'value',minInterval:1},series:[{name:'全部日志',type:'line',showSymbol:false,areaStyle:{opacity:.08},lineStyle:{color:'#2563eb'},itemStyle:{color:'#2563eb'},data:(trend.value.total||[]).map(([time,value])=>[new Date(time*1000),value])},{name:'错误日志',type:'line',showSymbol:false,lineStyle:{color:'#dc2626'},itemStyle:{color:'#dc2626'},data:(trend.value.errors||[]).map(([time,value])=>[new Date(time*1000),value])}]},true)}
function resizeChart(){chart?.resize()}
function sourceRate(key){return stats.total?((stats.sources?.[key]||0)*100/stats.total).toFixed(1):'0.0'}
function serviceWidth(count){const max=stats.top_services?.[0]?.count||1;return`${Math.max(3,count*100/max)}%`}
function formatTime(ns){const millis=Number(BigInt(ns)/1000000n);return new Date(millis).toLocaleString('zh-CN',{hour12:false})}
function exportText(){const content=entries.value.map(item=>`${formatTime(item.timestamp_ns)} [${item.labels?.source||'-'}] [${item.labels?.service_name||'-'}] ${item.line}`).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${currentHost.value?.name||'host'}-logs-${rangeKey.value}.log`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch(selectedHostId,()=>{controller?.abort();entries.value=[];if(status.ready)loadLogs()})
onMounted(async()=>{window.addEventListener('resize',resizeChart);await refreshHosts();await Promise.all([loadStatus(),loadAgentOverview(false)]);loadHealth();if(status.ready)loadLogs()})
onUnmounted(()=>{controller?.abort();chart?.dispose();window.removeEventListener('resize',resizeChart)})
</script>

<style scoped>
.status{display:flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%}.dot.ok{background:var(--ok)}.dot.warn{background:var(--warn)}.notice{padding:10px 14px;border-radius:8px;margin-bottom:12px}.error{background:#fef2f2;color:var(--err)}.collector-card{margin-bottom:14px;overflow:hidden}.collector-head{display:flex;align-items:center;justify-content:space-between;padding:15px 17px;border-bottom:1px solid var(--border)}.collector-head h3{margin:0 0 3px}.collector-actions{display:flex;gap:7px}.coverage-grid{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--border)}.coverage-grid>div{padding:13px 17px;border-right:1px solid var(--border)}.coverage-grid>div:last-child{border-right:0}.coverage-grid span,.collector-table small{display:block;color:var(--muted);font-size:12px}.coverage-grid b{display:block;font-size:22px;margin-top:5px}.collector-table{max-height:360px;overflow:auto}.collector-table .table{min-width:860px}.collector-table td small{margin-top:3px}.agent-state{display:inline-block;padding:2px 8px;border-radius:10px;font-size:12px}.agent-state.ok{color:var(--ok);background:rgba(34,197,94,.1)}.agent-state.error,.diagnostic.error{color:var(--err)}.agent-state.warn,.diagnostic.warning{color:var(--warn)}.agent-state.info,.diagnostic.info{color:var(--brand)}.diagnostic.ok{color:var(--ok)}.link-btn{border:0;background:none;color:var(--brand);cursor:pointer}.toolbar{padding:15px;margin-bottom:14px}.range-row,.custom,.filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.range-row b{font-size:13px}.range-btn{border:1px solid var(--border);background:var(--card);color:var(--muted);border-radius:999px;padding:5px 11px;cursor:pointer}.range-btn.active{background:var(--brand);border-color:var(--brand);color:white}.custom{margin-top:10px}.custom input,.filters input,.filters select{border:1px solid var(--border);border-radius:7px;padding:8px 10px;background:var(--card);color:var(--text)}.filters{border-top:1px solid var(--border);padding-top:12px;margin-top:12px}.filters input{min-width:210px}.results{padding:0;overflow:hidden}.result-head{display:flex;align-items:center;justify-content:space-between;padding:15px 17px;border-bottom:1px solid var(--border)}.result-head h3{margin:0 0 3px}.log-list{max-height:calc(100vh - 300px);min-height:300px;overflow:auto;background:#0b1220;color:#dbeafe;font:12px/1.55 Consolas,monospace}.log-line{display:grid;grid-template-columns:165px 64px 180px minmax(400px,1fr);gap:8px;padding:5px 12px;border-bottom:1px solid rgba(148,163,184,.08)}.log-line:hover{background:rgba(59,130,246,.08)}.log-line time{color:#94a3b8}.source{color:#38bdf8}.source.docker{color:#a78bfa}.service{color:#fbbf24;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.log-line pre{margin:0;white-space:pre-wrap;word-break:break-all;font:inherit}.empty{padding:50px;text-align:center;color:var(--muted)}@media(max-width:900px){.collector-head{align-items:flex-start;gap:10px;flex-direction:column}.coverage-grid{grid-template-columns:repeat(2,1fr)}.log-line{grid-template-columns:145px 58px minmax(300px,1fr)}.service{display:none}.filters input{min-width:160px}}
.loki-health{margin-bottom:14px;overflow:hidden}.health-warnings{display:flex;gap:7px;flex-wrap:wrap;padding:10px 17px;background:rgba(245,158,11,.08);border-bottom:1px solid var(--border)}.health-warnings span{color:var(--warn);font-size:12px}.health-grid{display:grid;grid-template-columns:repeat(5,1fr)}.health-grid>div{padding:14px 17px;border-right:1px solid var(--border)}.health-grid>div:last-child{border-right:0}.health-grid span,.health-grid small{display:block;color:var(--muted);font-size:12px}.health-grid b{display:block;font-size:21px;margin:6px 0}.health-grid b.danger{color:var(--err)}.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.stat{padding:15px}.stat span,.stat small{display:block;color:var(--muted);font-size:12px}.stat b{display:block;font-size:24px;margin:7px 0}.stat.danger b{color:var(--err)}.trend-card{margin-bottom:14px;overflow:hidden}.trend-chart{height:260px}.service-stats{padding:15px;margin-bottom:14px}.service-stats h3{margin:0 0 10px}.service-bars{display:grid;grid-template-columns:repeat(2,1fr);gap:6px 20px}.service-bars button{display:grid;grid-template-columns:150px 1fr 60px;align-items:center;gap:8px;border:0;background:none;color:var(--text);padding:4px;cursor:pointer;text-align:left}.service-bars i{height:6px;background:rgba(148,163,184,.2);border-radius:5px;overflow:hidden}.service-bars em{display:block;height:100%;background:var(--brand)}.service-bars b{text-align:right}@media(max-width:1100px){.health-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.health-grid{grid-template-columns:repeat(2,1fr)}.stats-grid{grid-template-columns:repeat(2,1fr)}.service-bars{grid-template-columns:1fr}}
</style>
